import hashlib

def anonymize_dataset(records: list[dict], fields: list[str]) -> list[dict]:
    anonymized = []
    for record in records:
        new_record = record.copy()
        for field in fields:
            if field in new_record:
                value = str(new_record[field])
                new_record[field] = hashlib.sha256(value.encode()).hexdigest()
        anonymized.append(new_record)
    return anonymized
```

