def detect_intrusion(packet_log: list[dict]) -> list[dict]:
    from collections import defaultdict

    failed_attempts = defaultdict(int)
    for packet in packet_log:
        if packet.get("status") == "failed":
            failed_attempts[packet.get("ip")] += 1

    return [
        {"ip": ip, "attempts": attempts, "type": "brute_force"}
        for ip, attempts in failed_attempts.items()
        if attempts >= 5
    ]
