import pyshark
from collections import Counter
import math

def calculate_entropy(domain: str) -> float:
    if not domain: return 0.0
    p, l = Counter(domain), len(domain)
    return -sum(count / l * math.log2(count / l) for count in p.values())

def analyze_dns_traffic(pcap_file: str) -> dict:
    suspicious = {"dga": [], "tunneling": [], "exfiltration": []}
    seen = set()

    capture = pyshark.FileCapture(pcap_file, display_filter='dns.flags.response == 0')
    for packet in capture:
        try:
            domain = packet.dns.qry_name.lower()
            if domain in seen: continue
            seen.add(domain)

            labels = domain.split('.')
            sld = labels[-2] if len(labels) >= 2 else domain

            if calculate_entropy(sld) > 3.5 or (sld.isalnum() and not any(v in sld for v in 'aeiou')):
                suspicious["dga"].append(domain)

            if len(domain) > 50 or any(len(l) > 30 for l in labels):
                suspicious["tunneling"].append(domain)

            if len(domain) > 100:
                suspicious["exfiltration"].append(domain)
        except AttributeError:
            continue

    capture.close()
    return suspicious
```

