def validate_sql_injection(url: str, params: dict) -> list[str]:
    vulnerable_params = []
    test_payloads = ["'", '"', "' OR '1'='1", '" OR "1"="1']

    for param in params:
        for payload in test_payloads:
            test_params = params.copy()
            test_params[param] = str(params[param]) + payload

            try:
                response = requests.get(url, params=test_params, timeout=5)

                # Leta efter vanliga databasfel som indikerar sårbarhet
                errors = ["sql syntax", "unclosed quotation mark", "mysql_fetch", "ORA-00936"]
                if any(error.lower() in response.text.lower() for error in errors):
                    if param not in vulnerable_params:
                        vulnerable_params.append(param)
                    break
            except requests.RequestException:
                pass

    return vulnerable_params
